CREATE TABLE IF NOT EXISTS departments (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(255));
CREATE TABLE IF NOT EXISTS employees (id BIGSERIAL PRIMARY KEY, employee_code VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255), email VARCHAR(255), phone VARCHAR(255), designation VARCHAR(255), joining_date DATE, employment_type VARCHAR(30), salary DOUBLE PRECISION, status VARCHAR(30), department_id BIGINT REFERENCES departments(id), manager_id BIGINT REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, name VARCHAR(255) NOT NULL, employee_id BIGINT UNIQUE REFERENCES employees(id), created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS attendance (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), work_date DATE NOT NULL, check_in TIMESTAMP, check_out TIMESTAMP, status VARCHAR(30), CONSTRAINT uq_attendance_employee_day UNIQUE(employee_id,work_date));
CREATE TABLE IF NOT EXISTS leave_balances (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL UNIQUE REFERENCES employees(id), leave_year INTEGER NOT NULL, casual_leave INTEGER NOT NULL, sick_leave INTEGER NOT NULL, earned_leave INTEGER NOT NULL, CONSTRAINT uq_leave_balance_employee_year UNIQUE(employee_id,leave_year));
CREATE TABLE IF NOT EXISTS leave_requests (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), start_date DATE, end_date DATE, type VARCHAR(50), reason VARCHAR(255), status VARCHAR(30), created_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS payrolls (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), period VARCHAR(20) NOT NULL, basic_salary DOUBLE PRECISION NOT NULL, hra DOUBLE PRECISION NOT NULL, allowances DOUBLE PRECISION NOT NULL, gross_salary DOUBLE PRECISION NOT NULL, pf DOUBLE PRECISION NOT NULL, tax DOUBLE PRECISION NOT NULL, other_deductions DOUBLE PRECISION NOT NULL, net_salary DOUBLE PRECISION NOT NULL, CONSTRAINT uq_payroll_employee_period UNIQUE(employee_id,period));
CREATE TABLE IF NOT EXISTS performance_reviews (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employees(id), review_date DATE, technical_skills DOUBLE PRECISION NOT NULL, communication DOUBLE PRECISION NOT NULL, teamwork DOUBLE PRECISION NOT NULL, productivity DOUBLE PRECISION NOT NULL, leadership DOUBLE PRECISION NOT NULL, overall_score DOUBLE PRECISION NOT NULL, feedback VARCHAR(255));
CREATE TABLE IF NOT EXISTS notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), title VARCHAR(255), message VARCHAR(255), read BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL);
